from pathlib import Path

WORKSPACE = Path("/data/agent_workspace").resolve()
ALLOWED_WRITE = {".md", ".csv", ".py", ".txt"}
MAX_READ_BYTES = 200_000

def _safe(path: str) -> Path:
    p = (WORKSPACE / path).resolve()
    if not str(p).startswith(str(WORKSPACE)):
        raise ToolError(f"path '{path}' escapes the workspace — "
                        "use paths relative to the working directory")
    return p

def read_file(path: str) -> str:
    p = _safe(path)
    if p.stat().st_size > MAX_READ_BYTES:
        raise ToolError(f"{p.name} is {p.stat().st_size:,} bytes (max "
                        f"{MAX_READ_BYTES:,}) — ask for a specific section")
    return p.read_text()

def write_file(path: str, content: str) -> str:
    p = _safe(path)
    if p.suffix not in ALLOWED_WRITE:
        raise ToolError(f"writes allowed only for {sorted(ALLOWED_WRITE)}")
    p.write_text(content)
    return f"wrote {len(content)} bytes to {p.name}"
